// mapper/employee/EmployeeMapper.java
package com.company.hrpayroll.mapper.employee;

import com.company.hrpayroll.dto.request.employee.EmployeeRequest;
import com.company.hrpayroll.dto.response.employee.EmployeeDirectoryResponse;
import com.company.hrpayroll.dto.response.employee.EmployeeResponse;
import com.company.hrpayroll.dto.response.employee.EmployeeSummaryResponse;
import com.company.hrpayroll.entity.employee.Employee;
import org.springframework.stereotype.Service;

@Service
public class EmployeeMapper {

    // employeeNumber is generated by the service layer (sequential/branch-coded)
    // and set separately — it's not something the client provides.
    public Employee toEmployee(EmployeeRequest dto) {
        return Employee.builder()
                .fullName(dto.fullName())
                .nationalId(dto.nationalId())
                .dateOfBirth(dto.dateOfBirth())
                .gender(dto.gender())
                .maritalStatus(dto.maritalStatus())
                .phone(dto.phone())
                .email(dto.email())
                .address(dto.address())
                .kraPin(dto.kraPin())
                .shifNumber(dto.shifNumber())
                .nssfNumber(dto.nssfNumber())
                .nitaNumber(dto.nitaNumber())
                .branchId(dto.branchId())
                .departmentId(dto.departmentId())
                .agentId(dto.agentId())
                .position(dto.position())
                .employmentType(dto.employmentType())
                .basicSalary(dto.basicSalary())
                .dateHired(dto.dateHired())
                .employmentStatus("ACTIVE")
                .bankName(dto.bankName())
                .bankAccountNumber(dto.bankAccountNumber())
                .emergencyContactName(dto.emergencyContactName())
                .emergencyContactPhone(dto.emergencyContactPhone())
                .build();
    }

    public void updateEmployeeFromRequest(Employee employee, EmployeeRequest dto) {
        employee.setFullName(dto.fullName());
        employee.setNationalId(dto.nationalId());
        employee.setDateOfBirth(dto.dateOfBirth());
        employee.setGender(dto.gender());
        employee.setMaritalStatus(dto.maritalStatus());
        employee.setPhone(dto.phone());
        employee.setEmail(dto.email());
        employee.setAddress(dto.address());
        employee.setKraPin(dto.kraPin());
        employee.setShifNumber(dto.shifNumber());
        employee.setNssfNumber(dto.nssfNumber());
        employee.setNitaNumber(dto.nitaNumber());
        employee.setBranchId(dto.branchId());
        employee.setDepartmentId(dto.departmentId());
        employee.setAgentId(dto.agentId());
        employee.setPosition(dto.position());
        employee.setEmploymentType(dto.employmentType());
        employee.setBasicSalary(dto.basicSalary());
        employee.setDateHired(dto.dateHired());
        employee.setBankName(dto.bankName());
        employee.setBankAccountNumber(dto.bankAccountNumber());
        employee.setEmergencyContactName(dto.emergencyContactName());
        employee.setEmergencyContactPhone(dto.emergencyContactPhone());
    }

    public EmployeeResponse toEmployeeResponse(
            Employee employee, String branchName, String departmentName, String agentName) {
        return new EmployeeResponse(
                employee.getId(),
                employee.getFullName(),
                employee.getEmployeeNumber(),
                employee.getPassportPhotoUrl(),
                employee.getNationalId(),
                employee.getDateOfBirth(),
                employee.getGender(),
                employee.getMaritalStatus(),
                employee.getPhone(),
                employee.getEmail(),
                employee.getAddress(),
                employee.getKraPin(),
                employee.getShifNumber(),
                employee.getNssfNumber(),
                employee.getNitaNumber(),
                employee.getBranchId(),
                branchName,
                employee.getDepartmentId(),
                departmentName,
                employee.getAgentId(),
                agentName,
                employee.getPosition(),
                employee.getEmploymentType(),
                employee.getBasicSalary(),
                employee.getDateHired(),
                employee.getEmploymentStatus(),
                employee.getBankName(),
                employee.getBankAccountNumber(),
                employee.getEmergencyContactName(),
                employee.getEmergencyContactPhone()
        );
    }

    public EmployeeDirectoryResponse toEmployeeDirectoryResponse(
            Employee employee, String departmentName, String agentName) {
        return new EmployeeDirectoryResponse(
                employee.getId(),
                employee.getEmployeeNumber(),
                employee.getFullName(),
                employee.getPhone(),
                departmentName,
                agentName,
                employee.getBasicSalary(),
                employee.getPosition(),
                employee.getEmploymentStatus()
        );
    }

    public EmployeeSummaryResponse toEmployeeSummaryResponse(Employee employee, String branchName) {
        return new EmployeeSummaryResponse(
                employee.getId(),
                employee.getFullName(),
                employee.getEmployeeNumber(),
                branchName,
                employee.getPosition(),
                employee.getEmploymentStatus()
        );
    }
}